  ('2026.12', 2, 'CA', 'Caminata activa', 'Caminata a paso vivo (o bicicleta suave del mismo tiempo)', 'Recuperación activa sin impacto de carrera'),
  ('2026.12', 3, 'REC', 'Trote de recuperación', 'Trote muy suave, más lento que el rodaje', 'Recuperación activa'),
  ('2026.12', 4, 'R', 'Rodaje', 'Carrera continua en Suave', 'Capacidad aeróbica (fase I)'),
  ('2026.12', 5, 'R+P', 'Rodaje con progresivos', 'Rodaje Suave + 6 × 100 m progresivos con 1''40" de trote', 'Economía y técnica sin fatiga'),
  ('2026.12', 6, 'RM', 'Rodaje medio', 'Rodaje Suave más largo (segunda sesión más larga de la semana)', 'Volumen y resistencia a la fatiga'),
