  ('2026.12', 10, 'INT', 'Intervalos', 'Repeticiones de 200–1500 m a ritmo de 3–10 km con pausa de trote', 'Potencia aeróbica (VO2máx)'),
  ('2026.12', 11, 'CUE', 'Cuestas', 'Subidas de 100–300 m al 4–6% con vuelta caminando o trotando', 'Fuerza específica y economía'),
  ('2026.12', 12, 'RC', 'Ritmo de competencia', 'Bloques al ritmo objetivo de 10 km, 21,1 km o maratón', 'Especificidad'),
  ('2026.12', 13, 'CTRL', 'Control', 'Test de 5 km o carrera de control', 'Evaluar y recalcular ritmos'),
  ('2026.12', 14, 'COMP', 'Competencia', 'Competencia intermedia u objetivo', 'Rendir y ensayar la estrategia'),
  ('2026.12', 15, '+F', 'Fuerza', 'Rutina A, B o C según el capítulo', 'Economía, tolerancia a la carga, prevención')
insert into public.library_strength_exercises (content_version, routine, position, exercise, target, sets_reps) values
