-- RUNNER 360 — Biblioteca de planes de running.
-- GENERADO por packages/plan-library/scripts/generate-seed.ts desde content/training-plans/running_plans_library.json.
-- No editar a mano: para cambiar el contenido, subí content_version en el JSON y regenerá.
-- runner360:reapply-on-change
begin;

-- Biblioteca de planes 2026.12 (huella 9cca01424fc16aad912bc3d7a71e82c19f8bb4af7e4238ef9d86f88aba9c72c0)

do $guard$
begin
  if exists (select 1 from public.library_versions where content_version = '2026.12' and checksum <> '9cca01424fc16aad912bc3d7a71e82c19f8bb4af7e4238ef9d86f88aba9c72c0') then
    raise exception 'La content_version % ya fue importada con otro contenido: subí content_version en el JSON', '2026.12';
  end if;
end
$guard$;

on conflict (content_version) do nothing;

on conflict (content_version, name) do nothing;

on conflict (content_version, code) do nothing;

on conflict (content_version, routine, position) do nothing;

on conflict (content_version, id) do nothing;

on conflict (content_version, plan_id, week) do nothing;

on conflict (content_version, plan_id, week) do nothing;

on conflict (content_version, plan_id, week, day_index) do nothing;

on conflict (content_version, plan_id, week, day_index) do nothing;

on conflict (content_version, plan_id, week, day_index) do nothing;

on conflict (content_version, plan_id, week, day_index) do nothing;

on conflict (content_version, plan_id, week, day_index) do nothing;

on conflict (content_version, plan_id, week, day_index) do nothing;

on conflict (content_version, plan_id, week, day_index) do nothing;

on conflict (content_version, plan_id, week, day_index) do nothing;

on conflict (content_version, plan_id, week, day_index) do nothing;

on conflict (content_version, plan_id, week, day_index) do nothing;

on conflict (content_version, plan_id, week, day_index) do nothing;

on conflict (content_version, plan_id, week, day_index) do nothing;

on conflict (content_version, plan_id, week, day_index) do nothing;

update public.library_versions set is_current = false where is_current and content_version <> '2026.12';

update public.library_versions set is_current = true where content_version = '2026.12' and not is_current;

commit;
